```apex
trigger CaseTrigger on Case (after update) {

    // Collect cases that just transitioned from not-closed to closed and
    // that have a contact (cases without a contact get no survey task).
    List<Id> newlyClosedWithContact = new List<Id>();
    for (Case c : Trigger.new) {
        Case prior = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !prior.IsClosed && c.ContactId != null) {
            newlyClosedWithContact.add(c.Id);
        }
    }

    if (newlyClosedWithContact.isEmpty()) {
        return;
    }

    // System.enqueueJob can be called at most 50 times per transaction, and a
    // nightly cleanup can close up to 200 cases at once. Chaining the overflow
    // isn't an option because chaining queueable jobs is not allowed in tests.
    // Instead we size our chunks so the number of jobs never exceeds the
    // remaining budget. In the common case (<= budget cases, e.g. an agent
    // closing a few from a list view) the chunk size is 1, so we enqueue one
    // job per case exactly as required. Each job runs in its own transaction,
    // so one failure cannot affect the others.
    Integer budget = Limits.getLimitQueueableJobs() - Limits.getQueueableJobs();
    if (budget < 1) {
        budget = 1;
    }

    Integer total = newlyClosedWithContact.size();
    Integer chunkSize = (Integer) Math.ceil((Decimal) total / budget);
    if (chunkSize < 1) {
        chunkSize = 1;
    }

    for (Integer i = 0; i < total; i += chunkSize) {
        Integer end = Math.min(i + chunkSize, total);
        List<Id> chunk = new List<Id>();
        for (Integer j = i; j < end; j++) {
            chunk.add(newlyClosedWithContact[j]);
        }
        System.enqueueJob(new CaseSurveyJob(chunk));
    }
}
