import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId;

    casesUrl;

    connectedCallback() {
        // Generate the Case list view URL on load and render it as an <a> href.
        this[NavigationMixin.GenerateUrl]({
            type: 'standard__objectPage',
            objectApiName: 'Case',
            actionName: 'list',
            state: {
                filterName: 'My_Open_Cases'
            }
        }).then((url) => {
            this.casesUrl = url;
        });
    }

    handleClick(event) {
        const action = event.currentTarget.dataset.action;

        switch (action) {
            case 'new-contact':
                this.navigateToNewContact();
                break;
            case 'contacts':
                this.navigateToContacts();
                break;
            case 'edit':
                this.navigateToEdit();
                break;
            default:
                break;
        }
    }

    navigateToNewContact() {
        const defaultFieldValues = encodeDefaultFieldValues({
            AccountId: this.recordId
        });

        this[NavigationMixin.Navigate]({
            type: 'standard__objectPage',
            objectApiName: 'Contact',
            actionName: 'new',
            state: {
                defaultFieldValues
            }
        });
    }

    navigateToContacts() {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordRelationshipPage',
            recordId: this.recordId,
            objectApiName: 'Account',
            relationshipApiName: 'Contacts',
            actionName: 'view'
        });
    }

    navigateToEdit() {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            recordId: this.recordId,
            objectApiName: 'Account',
            actionName: 'edit'
        });
    }
}
