/**
 * Returns the subset of supplied record IDs that the running user is allowed to edit,
 * honouring object permissions, ownership, sharing, the role hierarchy and
 * View All / Modify All, as reported by UserRecordAccess.HasEditAccess.
 *
 * UserRecordAccess only allows up to 200 RecordIds in the WHERE clause per query,
 * so the input is processed in chunks of 200. For the documented maximum of
 * 2,000 IDs this uses at most 10 SOQL queries (well within the 20 query budget).
 */
public with sharing class RecordAccessService {

    // Maximum number of RecordIds allowed in a single UserRecordAccess query.
    private static final Integer CHUNK_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Work from a list so we can slice it into chunks.
        List<Id> allIds = new List<Id>(recordIds);
        Id runningUserId = UserInfo.getUserId();

        for (Integer start = 0; start < allIds.size(); start += CHUNK_SIZE) {
            Integer stop = Math.min(start + CHUNK_SIZE, allIds.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < stop; i++) {
                chunk.add(allIds[i]);
            }

            for (UserRecordAccess ura : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                AND RecordId IN :chunk
            ]) {
                if (ura.HasEditAccess) {
                    result.add(ura.RecordId);
                }
            }
        }

        return result;
    }
}
