public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        Schema.DescribeSObjectResult objDesc = FB_Employee__c.SObjectType.getDescribe();

        // Respect object-level read access; if the user can't read the
        // object at all, return an empty list.
        if (!objDesc.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        // Always-queryable base fields (Id and Name are available whenever
        // the object is accessible).
        List<String> fieldsToQuery = new List<String>{ 'Id', 'Name' };

        // Only include the restricted custom fields the running user can
        // actually read; querying a field without FLS throws a QueryException.
        for (String fieldName : new List<String>{ 'Department__c', 'Salary__c', 'Personal_Email__c' }) {
            Schema.SObjectField f = fieldMap.get(fieldName.toLowerCase());
            if (f != null && f.getDescribe().isAccessible()) {
                fieldsToQuery.add(fieldName);
            }
        }

        // "with sharing" on the class enforces record-level sharing.
        String query =
            'SELECT ' + String.join(fieldsToQuery, ', ') +
            ' FROM FB_Employee__c ORDER BY Name ASC';

        List<FB_Employee__c> records = Database.query(query);

        // Defensive FLS enforcement: strip any inaccessible fields entirely
        // (they are absent, not nulled) and never throws for FLS.
        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            records
        );

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
