/**
 * Trigger Action (TAF) that keeps Account.FB_Open_Case_Count__c equal to the
 * number of that Account's Cases where IsClosed = false.
 *
 * Registered for after insert, after update, after delete and after undelete
 * on Case. Each context invocation uses at most one SOQL query (the aggregate
 * count) and one DML statement (the Account update), and is bulk-safe for 200
 * Cases per operation.
 */
public with sharing class TA_Case_RollupOpenCount implements
    TriggerAction.AfterInsert,
    TriggerAction.AfterUpdate,
    TriggerAction.AfterDelete,
    TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerNew) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldMap = new Map<Id, Case>((List<Case>) triggerOld);
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerNew) {
            Case oldCase = oldMap.get(c.Id);
            // Recalculate only when the Account link or open/closed state changed.
            if (c.AccountId != oldCase.AccountId || c.IsClosed != oldCase.IsClosed) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerOld) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : (List<Case>) triggerNew) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        recalculate(accountIds);
    }

    private void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Default every affected Account to 0 so that an account whose last open
        // case went away is set to 0 (not left blank/stale).
        Map<Id, Integer> countByAccountId = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            countByAccountId.put(accountId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            countByAccountId.put(
                (Id) ar.get('accId'),
                (Integer) ar.get('openCount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : countByAccountId.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                FB_Open_Case_Count__c = countByAccountId.get(accountId)
            ));
        }

        update accountsToUpdate;
    }
}
